export const CATEGORIES={coffee:{label:'咖啡记录',color:'#22d3c5'},office_building:{label:'办公建筑',color:'#b998ff'},shopping_center:{label:'购物中心',color:'#fbbf52'},subway_entrance:{label:'地铁出入口',color:'#79b4ff'}};
// Vincenty inverse on WGS84. Beijing analysis distances converge; no spherical result is silently substituted.
export function distance(lon1,lat1,lon2,lat2){
 if(![lon1,lat1,lon2,lat2].every(Number.isFinite))throw new Error('坐标必须是有限数值');
 if(lon1===lon2&&lat1===lat2)return 0;
 const a=6378137,f=1/298.257223563,b=(1-f)*a,toRad=Math.PI/180,U1=Math.atan((1-f)*Math.tan(lat1*toRad)),U2=Math.atan((1-f)*Math.tan(lat2*toRad)),L=(lon2-lon1)*toRad;
 const s1=Math.sin(U1),c1=Math.cos(U1),s2=Math.sin(U2),c2=Math.cos(U2);let lam=L,sinSigma,cosSigma,sigma,sinAlpha,cosSqAlpha,cos2SigmaM,converged=false;
 for(let i=0;i<200;i++){const sl=Math.sin(lam),cl=Math.cos(lam);sinSigma=Math.hypot(c2*sl,c1*s2-s1*c2*cl);if(sinSigma===0)return 0;cosSigma=s1*s2+c1*c2*cl;sigma=Math.atan2(sinSigma,cosSigma);sinAlpha=c1*c2*sl/sinSigma;cosSqAlpha=1-sinAlpha*sinAlpha;cos2SigmaM=cosSqAlpha<1e-15?0:cosSigma-2*s1*s2/cosSqAlpha;const C=f/16*cosSqAlpha*(4+f*(4-3*cosSqAlpha)),prev=lam;lam=L+(1-C)*f*sinAlpha*(sigma+C*sinSigma*(cos2SigmaM+C*cosSigma*(-1+2*cos2SigmaM*cos2SigmaM)));if(Math.abs(lam-prev)<1e-12){converged=true;break;}}
 if(!converged)throw new Error('距离计算未收敛，请检查坐标');
 const uSq=cosSqAlpha*(a*a-b*b)/(b*b),A=1+uSq/16384*(4096+uSq*(-768+uSq*(320-175*uSq))),B=uSq/1024*(256+uSq*(-128+uSq*(74-47*uSq))),delta=B*sinSigma*(cos2SigmaM+B/4*(cosSigma*(-1+2*cos2SigmaM**2)-B/6*cos2SigmaM*(-3+4*sinSigma**2)*(-3+4*cos2SigmaM**2)));
 return b*A*(sigma-delta);
}
export function validatePoint(point){if(!point||!Number.isFinite(point.lon)||!Number.isFinite(point.lat)||point.lon<115.4||point.lon>117.6||point.lat<39.4||point.lat>41.1)throw new Error('请输入北京范围内的 WGS84 坐标：经度在前、纬度在后。');if(typeof point.name!=='string'||!point.name.trim()||point.name.length>60)throw new Error('请输入 1～60 字的候选区域名称。');return point;}
export function analyze(point,pois){validatePoint(point);const buckets=Object.fromEntries(Object.keys(CATEGORIES).map(k=>[k,[]]));let excluded=[],nearest=null;for(const p of pois){const d=distance(point.lon,point.lat,p.lon,p.lat);if(p.included&&buckets[p.category]){if(d<=1000)buckets[p.category].push({...p,distance:d});if(p.category==='subway_entrance'&&d<=3000&&(!nearest||d<nearest.distance))nearest={...p,distance:d};}else if(d<=1000)excluded.push({...p,distance:d});}for(const a of Object.values(buckets))a.sort((a,b)=>a.distance-b.distance);excluded.sort((a,b)=>a.distance-b.distance);return{point,buckets,excluded,nearest,counts:Object.fromEntries(Object.entries(buckets).map(([k,v])=>[k,v.length])),coverageWarning:Object.values(buckets).some(x=>x.length===0)};}
export function explanation(result){const c=result.counts;return `${result.point.name} 的 1 km 范围内，冻结数据收录 ${c.coffee} 条咖啡记录、${c.office_building} 个办公建筑、${c.shopping_center} 个购物中心及 ${c.subway_entrance} 个地铁出入口。${result.nearest?`最近收录的地铁出入口直线距离约 ${Math.round(result.nearest.distance)} m。`:'3 km 内未找到有效地铁入口记录。'}${result.excluded.length?`另有 ${result.excluded.length} 条记录因类别待确认、层级不一致或质量问题未计入。`:''} 这些结果描述收录数据，不代表真实客流、完整竞品数量或盈利能力。`;}
